<?php
require_once "../db.php";requireAdmin();$repo=new ReservationRepository($pdo);
if($_SERVER["REQUEST_METHOD"]==="POST"){$id=filter_input(INPUT_POST,"reservation_id",FILTER_VALIDATE_INT);$ok=$id&&$repo->setAdminStatus($id,$_POST["status"]??"");header("Location: index.php?updated=".($ok?"1":"0")."#reservations");exit;}
$stats=$repo->statistics();$search=trim($_GET["q"]??"");$status=$_GET["status"]??"";$rows=$repo->all($search,$status);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard | CoworkSpace</title><link rel="stylesheet" href="../assets/style.css"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><header class="navbar"><div class="container nav-content"><a class="logo" href="index.php">Cowork<span>Admin</span></a><nav class="nav-links"><a href="../index.php">Website</a><a href="spaces.php">Spaces</a><a href="time-slots.php">Time slots</a><a href="users.php">Users</a><a href="../logout.php">Log out</a></nav></div></header><main class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">CONTROL CENTER</span><h1>Admin dashboard</h1></div><span class="muted">Welcome, <?=htmlspecialchars($_SESSION["name"]??"Admin")?></span></div><div class="stats-grid"><?php foreach(["total"=>"Reservations","pending"=>"Pending","confirmed"=>"Confirmed","users"=>"Users"] as $k=>$label):?><article class="stat-card"><span><?=htmlspecialchars($label)?></span><strong><?=(int)$stats[$k]?></strong></article><?php endforeach;?></div><div class="admin-grid"><section class="panel"><span class="eyebrow">OVERVIEW</span><h2>Reservations by status</h2><div class="chart-wrap"><canvas id="statusChart"></canvas></div></section><section class="panel quick-links"><span class="eyebrow">MANAGE</span><h2>Workspace tools</h2><a href="spaces.php">Manage spaces <span>-></span></a><a href="time-slots.php">Manage time slots <span>-></span></a><a href="users.php">Manage users <span>-></span></a></section></div><section id="reservations" class="panel"><div class="section-heading"><div><span class="eyebrow">BOOKING QUEUE</span><h2>Manage reservations</h2></div></div><?php if(isset($_GET["updated"])):?><div class="alert <?=($_GET["updated"]==="1")?"success":"error"?>"><?=($_GET["updated"]==="1")?"Status updated.":"That status change is not allowed."?></div><?php endif;?><form class="filter-bar" method="GET"><input type="search" name="q" value="<?=htmlspecialchars($search)?>" placeholder="Search name or email"><select name="status"><option value="">All statuses</option><?php foreach(["pending","confirmed","rejected","cancelled"] as $s):?><option value="<?=$s?>" <?=$status===$s?"selected":""?>><?=ucfirst($s)?></option><?php endforeach;?></select><button class="btn btn-small">Filter</button><a class="btn btn-outline btn-small" href="index.php#reservations">Clear</a></form><?php if(!$rows):?><div class="empty-state compact"><p>No reservations match this filter.</p></div><?php else:?><div class="table-wrapper"><table><thead><tr><th>User</th><th>Email</th><th>Space</th><th>Date</th><th>Time</th><th>Note</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r["user_name"])?></td><td><?=htmlspecialchars($r["user_email"])?></td><td><?=htmlspecialchars($r["space_name"])?></td><td><?=htmlspecialchars($r["booking_date"])?></td><td><?=htmlspecialchars(substr($r["start_time"],0,5))?>-<?=htmlspecialchars(substr($r["end_time"],0,5))?></td><td><?=htmlspecialchars($r["note"]??"")?></td><td><span class="badge badge-<?=htmlspecialchars($r["status"])?>"><?=htmlspecialchars(ucfirst($r["status"]))?></span></td><td><?php if(in_array($r["status"],["pending","confirmed"],true)):?><form method="POST" class="inline-form"><input type="hidden" name="reservation_id" value="<?=(int)$r["id"]?>"><select name="status"><?php if($r["status"]==="pending"):?><option value="confirmed">Confirm</option><option value="rejected">Reject</option><?php endif;?><option value="cancelled">Cancel</option></select><button class="btn btn-small">Save</button></form><?php else:?><span class="muted">Closed</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main><footer class="footer"><div class="container">CoworkSpace Admin</div></footer><script>new Chart(document.getElementById("statusChart"),{type:"doughnut",data:{labels:["Pending","Confirmed","Rejected","Cancelled"],datasets:[{data:[<?=$stats["pending"]?>,<?=$stats["confirmed"]?>,<?=$stats["rejected"]?>,<?=$stats["cancelled"]?>],backgroundColor:["#e9a23b","#348a75","#d76565","#94a3b8"],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom"}}}});</script></body></html>
